// Express-style chain: identity first, permission second, scope last.
const express = require("express")
const app = express()

// Layer 1: authentication — who is this? (401 on failure)
function authenticate(req, res, next) {
  const user = lookupSession(req.cookies.sid) // server-side session store
  if (!user) return res.status(401).json({ error: "unauthenticated" })
  req.user = user
  next()
}

// Layer 2: authorization — may this identity do this action? (403 on failure)
function requirePermission(action) {
  return (req, res, next) => {
    if (!hasPermission(req.user, action)) {
      return res.status(403).json({ error: "forbidden" })
    }
    next()
  }
}

// Layer 3: data scoping — even authorized users only see their own rows.
app.get("/invoices/:id", authenticate, requirePermission("invoice:read"),
  async (req, res) => {
    const invoice = await db.invoices.findOne({
      id: req.params.id,
      ownerId: req.user.id // scope in the query itself: defense in depth
    })
    if (!invoice) return res.status(404).end()
    res.json(invoice)
  })
